sys_script_include.script:
var LeaveRequestUtils = Class.create();
LeaveRequestUtils.prototype = {
    initialize: function() {},
    /**
     * Validates a date range given as internal date strings (yyyy-MM-dd).
     * @returns {{valid:boolean, message:string, days:number}}
     */
    validateRange: function(startStr, endStr) {
        if (!startStr || !endStr) {
            return {
                valid: false,
                message: 'Start Date and End Date are required.',
                days: 0
            };
        }
        var s = new GlideDate();
        s.setValue(startStr);
        var e = new GlideDate();
        e.setValue(endStr);
        var diffMs = e.getNumericValue() - s.getNumericValue();
        if (diffMs < 0) {
            return {
                valid: false,
                message: 'End Date cannot be earlier than Start Date.',
                days: 0
            };
        }
        // +1 because both the first and last day are leave days (calendar days, v1)
        return {
            valid: true,
            message: '',
            days: Math.round(diffMs / 86400000) + 1
        };
    },
    /**
     * True if the employee already has a Submitted or Approved request overlapping the range.
     * excludeSysId lets the record being saved ignore itself.
     */
    hasOverlap: function(employeeSysId, startStr, endStr, excludeSysId) {
        var gr = new GlideRecord('x_2236918_leavef_1_leave_request');
        gr.addQuery('employee', employeeSysId);
        gr.addQuery('status', 'IN', 'submitted,approved');
        gr.addQuery('start_date', '<=', endStr);
        gr.addQuery('end_date', '>=', startStr);
        if (excludeSysId) {
            gr.addQuery('sys_id', '!=', excludeSysId);
        }
        gr.setLimit(1);
        gr.query();
        return gr.hasNext();
    },
    /** Friendly label for a status value, used by notifications. */
    statusLabel: function(value) {
        var map = {
            draft: 'Draft',
            submitted: 'Awaiting approval',
            approved: 'Approved',
            rejected: 'Rejected',
            cancelled: 'Cancelled'
        };
        return map[value] || value;
    },
    type: 'LeaveRequestUtils'
};
